import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        target_user TEXT,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role for directory listing.
    Supports partial matching for department names.
    """
    department = request.args.get('department', '')
    role = request.args.get('role', 'user')
    active_only = request.args.get('active', '1')

    # Build query with filters
    # Note: role is validated against allowed list
    allowed_roles = ['user', 'admin', 'manager', 'readonly']
    if role not in allowed_roles:
        role = 'user'

    # Department supports LIKE matching for partial searches
    query = f"SELECT username, email, department, role FROM users WHERE department LIKE '%{department}%' AND role = '{role}' AND active = {active_only}"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]

        # Log the search action
        log_query = "INSERT INTO audit_log (action, target_user, performed_by) VALUES (?, ?, ?)"
        db.execute(log_query, ('search', f'dept:{department}', request.remote_addr))
        db.commit()

        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - parameterized query."""
    db = get_db()
    cursor = db.execute('SELECT username, email, department, role FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user - admin only (enforced by upstream auth)."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, department, role) VALUES (?, ?, ?, ?)',
            (data['username'], data['email'], data.get('department', ''), data.get('role', 'user'))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'db': os.path.exists(DATABASE)})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
